// Small, conservative English noun inflector; arithmetic is always rechecked afterward.
const studioWordForms=(()=>{
 const irregular={bus:'buses',status:'statuses',alias:'aliases',quiz:'quizzes',gas:'gases',cookie:'cookies',movie:'movies',pie:'pies',tie:'ties',die:'dice',shoe:'shoes',hero:'heroes',potato:'potatoes',tomato:'tomatoes',echo:'echoes',person:'people',man:'men',woman:'women',child:'children',mouse:'mice',goose:'geese',tooth:'teeth',foot:'feet',ox:'oxen',leaf:'leaves',knife:'knives',life:'lives',wife:'wives',wolf:'wolves',elf:'elves',shelf:'shelves',half:'halves',loaf:'loaves',thief:'thieves',analysis:'analyses',crisis:'crises'};
 const phraseNouns=new Set('heart voice song dawn moon star path garden flame light mind dream friend spirit river sea flower sky home beginning car bus train road window door table chair sword wish story child mouse box watch city leaf knife room book question answer end dragon kraken djinn shade ghost warrior mage knight hermit scholar sage traveler seeker boat mountain ocean cloud storm loss fear doubt choice boundary mistake chance word note arrow instrument student teacher artist musician player game world stone tree hand eye foot'.split(' '));
 const reverse=Object.fromEntries(Object.entries(irregular).map(([a,b])=>[b,a]));
 const fixed=new Set('news music wisdom knowledge equipment information advice rice water air love peace chaos fish sheep deer species series means glass grass brass chess happiness darkness kindness business abyss atlas cosmos'.split(' '));
 function noun(word){const w=word.toLowerCase();if(!/^[a-z]+$/.test(w)||fixed.has(w))return[];if(irregular[w])return[irregular[w]];if(reverse[w])return[reverse[w]];if(/ies$/.test(w)&&w.length>4)return[w.slice(0,-3)+'y'];if(/(?:ches|shes|sses|xes|zzes)$/.test(w))return[w.slice(0,-2)];if(/s$/.test(w)&&!/(?:ss|us|is)$/.test(w))return[w.slice(0,-1)];if(/[^aeiou]y$/.test(w))return[w.slice(0,-1)+'ies'];return[w+(/(?:s|x|z|ch|sh)$/.test(w)?'es':'s')];}
 function variants(text){const clean=String(text).trim(),match=clean.match(/^(.*?)([a-z]+)$/i);if(!match||clean.length>120)return[];if(match[1]&&!phraseNouns.has(match[2].toLowerCase())&&!phraseNouns.has(reverse[match[2].toLowerCase()])&&!noun(match[2]).some(n=>phraseNouns.has(n)))return[];return noun(match[2]).map(n=>{let prefix=match[1];if(/^an? $/i.test(prefix))prefix='';else if(/^an? /i.test(prefix))prefix=prefix.replace(/^an? /i,'');return prefix+n;}).filter(x=>x!==clean);}
 const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z]/g,'');
 const ch={A:1,I:1,J:1,Q:1,Y:1,B:2,K:2,R:2,C:3,G:3,L:3,S:3,D:4,M:4,T:4,E:5,H:5,N:5,X:5,U:6,V:6,W:6,O:7,Z:7,F:8,P:8};
 function sum(text,system){return [...normalize(text)].reduce((v,c)=>v+(system==='chaldean'?ch[c]:system==='pythagorean'?(c.charCodeAt(0)-65)%9+1:c.charCodeAt(0)-64),0);}
 function verify(candidates,system,targets){if(!['ordinal','pythagorean','chaldean'].includes(system))return[];const want=new Set((Array.isArray(targets)?targets:[]).filter(n=>Number.isInteger(n)&&n>0&&n<=3120)),seen=new Set(),out=[];for(const raw of (Array.isArray(candidates)?candidates:[]).slice(0,120)){const original=typeof raw==='string'?raw:raw?.text;if(typeof original!=='string'||original.length>120)continue;for(const text of [original.trim(),...variants(original)]){const key=normalize(text),total=sum(text,system);if(!key||seen.has(key)||!want.has(total))continue;seen.add(key);out.push({text,total,source:text===original.trim()?'AI suggestion · total verified':'AI suggestion · grammar variant verified',theme:'Open association'});}}return out;}
 return{variants,sum,verify,normalize};
})();

