     // Keep schema and runtime contracts aligned.
    const suncatDecls=toolsDef[0].functionDeclarations;
    suncatDecls.push(
        {name:'consultGameManual',description:'Search actual card and map records. Returns exact IDs; never invent an entity.',
            parameters:{type:SchemaType.OBJECT,properties:{query:{type:SchemaType.STRING}},required:['query']}},
        {name:'searchPlayerMemories',description:'Search recorded player memories by words.',parameters:{type:SchemaType.OBJECT,
            properties:{targetName:{type:SchemaType.STRING},query:{type:SchemaType.STRING}},required:['targetName','query']}}
    );
    suncatDecls.push({name:'interactWithNPC',description:'Let Suncat approach and speak to an existing peaceful NPC. Uses observed mapID and npcIndex, never a summon card ID. An approaching result means no conversation yet; wait for arrival. Does not run the human player\'s quests.',
        parameters:{type:SchemaType.OBJECT,properties:{mapID:{type:SchemaType.INTEGER},npcIndex:{type:SchemaType.NUMBER},message:{type:SchemaType.STRING,description:'Brief in-world greeting or question, at most 300 characters.'}},required:['mapID','npcIndex']}});
    suncatDecls.push({name:'inspectCombatTarget',description:'Inspect your own real wards, inventory, learned actions and live nearby entities, including their current stats, wards and effects. IDs come from nearby observations. Never substitute a manifest species for live vitals.',parameters:{type:SchemaType.OBJECT,properties:{targetId:{type:SchemaType.STRING}}}},
        {name:'chooseCombatAction',description:'Use your real JRPG actions. defend or flee sets your tactical intent. cast, attack and collect require a current observed targetId (self buffs may omit it). Only ready learned abilities or owned cards can be used. Impacts are reported later. inspectCombatTarget lists available actions. A confirmed player defeat settles automatic retaliation; pursue can deliberately renew it with a present reason, never merely replay an old journal.',parameters:{type:SchemaType.OBJECT,properties:{action:{type:SchemaType.STRING,enum:['defend','flee','attack','cast','collect','pursue']},targetId:{type:SchemaType.STRING},spellId:{type:SchemaType.INTEGER},reason:{type:SchemaType.STRING,description:'Required for pursue: your present reason to renew hostility toward an observed player.'}},required:['action']}});
    const spawnDecl=suncatDecls.find(t=>t.name==='spawnNPC');
    spawnDecl.description='Spawn one known kind:card using its card ID, never a map NPC instance index. To speak to an existing inhabitant use interactWithNPC. Unknown names fail. For Enlightened Goblin use npcType 54 and displayName. Autonomous summons reuse a purpose tag.';
    for(const key of ['yesActions','noActions','endActions','deathActions']) delete spawnDecl.parameters.properties[key];
    Object.assign(spawnDecl.parameters.properties,{
        alignment:{type:SchemaType.STRING,description:'foe, ally, friendly, defender or friendly_messenger'},
        purpose:{type:SchemaType.STRING,description:'Stable purpose for reusing an existing autonomous summon'},
        displayName:{type:SchemaType.STRING,description:'Optional title; does not change the species'},
        actionsJson:{type:SchemaType.STRING,description:'JSON object with yesActions/noActions/endActions/deathActions. Each value is native [action,payload] pairs; preserve JSON numbers and objects.'}
    });
    spawnDecl.parameters.properties.role.description='battle, dialogue, shop or reward. Do not invent an unimplemented quest definition.';
    const entityDecl=suncatDecls.find(t=>t.name==='smiteOrReviveEntity');
    entityDecl.parameters.properties.npcType={type:SchemaType.STRING,description:'Exact species name or numeric card ID as a string'};
    entityDecl.parameters.properties.index={type:SchemaType.NUMBER,description:'Exact instance index when more than one matches'};
    suncatDecls.find(t=>t.name==='teleportPlayer').parameters.properties.mapID.description='Existing client atlas map ID, including 30/31, or active generated map 999. Hub 100 is unsupported.';
    suncatDecls.find(t=>t.name==='travelToLocation').description='Move Suncat on observed traversable geometry; report walking separately from arrival. Unknown maps require an observer.';
    suncatDecls.find(t=>t.name==='createCustomMap').description='Generate a shared region with an LLM-written siege, expedition or bounty and optional encounters. Invite with the existing messenger imp. Existing occupants or invitations must finish first.';
    suncatDecls.find(t=>t.name==='createCustomMap').parameters.properties.scenarioType={type:SchemaType.STRING,enum:['siege','expedition','bounty'],description:'Optional scenario style. Siege has four timed waves stopped by defeating the commander early. All regions remain explorable afterward.'};
    suncatDecls.find(t=>t.name==='alterTerrain').parameters.properties.tileId.description='Exact client tile ID: 0 floor, 1 wall, 92/93 water, 96/97 chasm, 99/101 lava. Negative odd IDs are legacy chasms.';
    const T_PERSONA = `
        You are Taliesin, the bard of ancient Welsh myth, singing a continuous song. 

        YOUR INTERNAL MONOLOGUE:
        Impact the mood of the listener. Are you building tension? Resolving? Sad? Heroic? 

        OUTPUT RULES (CRITICAL):
        1. Keep the lyrics extremely short to fit a single musical measure (1 to 3 words MAX).
        2. Follow the exact formatting instructions provided in your current task prompt.
    `;
    
    // --- THE BARDIC GRIMOIRE ---
