                    const bind=ready.find(a=>SUNCAT_SPELLS[a.id].bind&&!t.effects?.some(e=>e.bind));
                    const best=(flee&&heal)||((flee||dist<3)&&bind)||ready.find(a=>a.id!==9999&&a.type==='projectile')||(dist<=1.3&&ready.find(a=>a.id===9999));
