   if(p!==old){unqueue(p);people.delete(p.id);}old.packed=p.packed;old.flow88=p.flow88;resetFlow88(old);old.context=context;old.disconnectedAt=null;context.summoner86=old;p=old;
   publish();return ok({state:fullState(p.room),roomId:p.room.id,playerId:p.id});
