   const TYPES=['jump','dash','attack','skill','spell','ultimate','item','chargeStart','chargeEnd','upgrade','respawn','king','maneuver'];
   if(!Number.isSafeInteger(payload.sequence)||payload.sequence<0||!TYPES.includes(payload.type)||payload.key!==undefined&&(typeof payload.key!=='string'||payload.key.length>48)||payload.target!==undefined&&!['number','string'].includes(typeof payload.target))return fail('Invalid action.');
